123:  private:
124:   struct Param {
125:     const ORTCHAR_T* name_prefix;
126:     int index;
127:     unsigned (*start_address)(int id, Eigen::ThreadPoolInterface* param);
128:     Eigen::ThreadPoolInterface* param;
