130: 
131:     Param(const ORTCHAR_T* name_prefix1,
132:           int index1,
133:           unsigned (*start_address1)(int id, Eigen::ThreadPoolInterface* param),
134:           Eigen::ThreadPoolInterface* param1)
135:         : name_prefix(name_prefix1),
136:           index(index1),
137:           start_address(start_address1),
138:           param(param1) {}
139:   };
