141:  public:
142:   PosixThread(const ORTCHAR_T* name_prefix, int index,
143:               unsigned (*start_address)(int id, Eigen::ThreadPoolInterface* param), Eigen::ThreadPoolInterface* param,
144:               const ThreadOptions& thread_options) {
145:     ORT_ENFORCE(index >= 0, "Negative thread index is not allowed");
146:     custom_create_thread_fn = thread_options.custom_create_thread_fn;
147:     custom_thread_creation_options = thread_options.custom_thread_creation_options;
148:     custom_join_thread_fn = thread_options.custom_join_thread_fn;
149: 
150:     auto param_ptr = std::make_unique<Param>(name_prefix, index, start_address, param);
151:     if (narrow<size_t>(index) < thread_options.affinities.size()) {
152:       param_ptr->affinity = thread_options.affinities[index];
153:     }
154: 
155:     if (custom_create_thread_fn) {
156:       custom_thread_handle = custom_create_thread_fn(custom_thread_creation_options, CustomThreadMain, param_ptr.get());
157:       if (!custom_thread_handle) {
158:         ORT_THROW("custom_create_thread_fn returned invalid handle.");
159:       }
160:       param_ptr.release();
161:     } else {
162:       pthread_attr_t attr;
163:       int s = pthread_attr_init(&attr);
164:       if (s != 0) {
165:         auto [err_no, err_msg] = GetErrnoInfo();
166:         ORT_THROW("pthread_attr_init failed, error code: ", err_no, " error msg: ", err_msg);
167:       }
168: 
169:       size_t stack_size = thread_options.stack_size;
170:       if (stack_size > 0) {
171:         s = pthread_attr_setstacksize(&attr, stack_size);
172:         if (s != 0) {
173:           auto [err_no, err_msg] = GetErrnoInfo();
174:           ORT_THROW("pthread_attr_setstacksize failed, error code: ", err_no, " error msg: ", err_msg);
175:         }
176:       }
177: 
178:       s = pthread_create(&hThread, &attr, ThreadMain, param_ptr.get());
179:       if (s != 0) {
180:         auto [err_no, err_msg] = GetErrnoInfo();
181:         ORT_THROW("pthread_create failed, error code: ", err_no, " error msg: ", err_msg);
182:       }
183:       param_ptr.release();
184:       // Do not throw beyond this point so we do not lose thread handle and then not being able to join it.
185:     }
186:   }
