188:   ~PosixThread() override {
189:     if (custom_thread_handle) {
190:       custom_join_thread_fn(custom_thread_handle);
191:       custom_thread_handle = nullptr;
192:     } else {
193:       void* res;
194: #ifdef NDEBUG
195:       pthread_join(hThread, &res);
196: #else
