203:  private:
204:   static void* ThreadMain(void* param) {
205:     std::unique_ptr<Param> p(static_cast<Param*>(param));
206:     ORT_TRY {
207: #if !defined(__APPLE__) && !defined(__ANDROID__) && !defined(__wasm__) && !defined(_AIX)
208:       if (p->affinity.has_value() && !p->affinity->empty()) {
209:         cpu_set_t cpuset;
