215:             // Logical processor id starts from 0 internally, but in ort API, it starts from 1,
216:             // that's why id need to increase by 1 when logging.
217:             LOGS_DEFAULT(ERROR) << "cpu " << id + 1 << " does not exist, skipping it for affinity setting";
218:           }
