221:         if (0 == ret) {
222:           LOGS_DEFAULT(VERBOSE) << "pthread_setaffinity_np succeed for thread: " << syscall(SYS_gettid)
223:                                 << ", index: " << p->index
224:                                 << ", mask: " << *p->affinity;
225:         } else {
226:           errno = ret;
227:           auto [err_no, err_msg] = GetErrnoInfo();
228:           LOGS_DEFAULT(ERROR) << "pthread_setaffinity_np failed for thread: " << syscall(SYS_gettid)
229:                               << ", index: " << p->index
230:                               << ", mask: " << *p->affinity
231:                               << ", error code: " << err_no << " error msg: " << err_msg
232:                               << ". Specify the number of threads explicitly so the affinity is not set.";
233:         }
234:       }
235: #endif
